class Solution {
    fun countBlackBlocks(m:Int,n:Int,coordinates:Array<IntArray>):LongArray{
        val count=HashMap<Long,Int>();
        for(cell in coordinates)for(dr in -1..0)for(dc in -1..0){
            val row=cell[0]+dr;
            val col=cell[1]+dc;
            if(row>=0&&row<m-1&&col>=0&&col<n-1){
                val key=row.toLong()*n+col;
                count[key]=(count[key]?:0)+1
            }
        };
        val answer=LongArray(5);
        answer[0]=(m-1).toLong()*(n-1)-count.size;
        for(value in count.values)answer[value]++;
        return answer
    }
}

