class Solution {
    public:vector<long long> countBlackBlocks(int m,int n,vector<vector<int>>& coordinates){
        unordered_map<long long,int> count;
        for(auto& cell:coordinates)for(int dr=-1;dr<=0;++dr)for(int dc=-1;dc<=0;++dc){
            int row=cell[0]+dr,col=cell[1]+dc;
            if(row>=0&&row<m-1&&col>=0&&col<n-1)++count[(long long)row*n+col];
        }
        vector<long long> answer(5);
        answer[0]=(long long)(m-1)*(n-1)-count.size();
        for(auto [key,value]:count)++answer[value];
        return answer;
    }
};
